              className="w-full bg-blue-600 hover:bg-blue-500 text-white py-7 text-lg rounded-xl transition-transform hover:scale-[1.02] shadow-lg shadow-blue-600/20"
            >
              {loading ? "Processando..." : "Adquirir Agora - R$ 50"}
